var lowering = runtime.Lowering{
	Frag:  fragOf,
	Order: orderOf,
	OB:    runtime.Order{Lead: " ORDER BY ", Sep: ", "},
	Ident: func(col uint32) string {
		if col >= nCols {
			return ""
		}
		return identTable[col]
	},
	RowCmp: func(op uint32) string {
		if op == runtime.CmpLt {
			return " < "
		}
		return " > "
	},
	TupleOpen:  "(",
	TupleSep:   ", ",
	TupleClose: ")",
}

func orderOf(dir, col uint32) string {
	if col >= nCols || int(dir) >= len(orderTable[0]) {
		return ""
	}
	return orderTable[col][dir]
}

